args <- commandArgs(trailingOnly=FALSE)
root <- normalizePath(file.path(dirname(sub("^--file=","",grep("^--file=",args,value=TRUE)[[1L]])),".."),winslash="/")
library(data.table)
source(file.path(root,"R","state_destinations.R"))
rows <- data.table(source_id=as.character(1:6),cycle=c(2024L,2024L,2024L,2024L,2024L,2026L),cycle_label=c(rep("2023-2024",5),"2025-2026"),company="Example",party="D",committee_id=c("C1","C2","C3","C4","C5","C1"),amount=c(100,-10,30,40,50,60),include_in_analysis="Yes")
committees <- data.table(cycle=2024L,committee_id=c("C1","C2","C3","C4"),state=c("DC","NY","CA",""),source_url="official committee fixture")
candidates <- data.table(cycle=2024L,candidate_id=c("H1","H2","H3","P1"),office=c("H","H","H","P"),office_state=c("VA","TX","TX","CA"),source_url="official candidate fixture")
links <- data.table(cycle=2024L,committee_id=c("C1","C2","C2","C3"),candidate_id=c("H1","H2","H3","P1"),designation="P",source_url="official linkage fixture")
result <- mentat_add_destinations(rows,committees,candidates,links)
stopifnot(identical(result$source_id,rows$source_id),identical(result$amount,rows$amount),nrow(result)==6L)
stopifnot(result$recipient_state[1]=="DC",result$represented_state[1]=="VA",result$represented_state[2]=="Ambiguous",result$represented_state[3]=="National / N/A",result$recipient_state[4]=="Unknown",result$recipient_state[6]=="Unknown",result$represented_state[6]=="Unknown")
summary <- mentat_state_destinations(result)
stopifnot(all(summary[,.(total=sum(net_amount)),by=location_view]$total==270),sum(summary$receipt_count)==12L)
cat("State destination identity, cycle isolation, ambiguity, national/unknown, negative amounts and both partition totals: PASS\n")
